// Die Funktion formatiert Bibelstellenangaben so,
// dass die Verszahlen etwas kleiner dargestellt werden
// und die gesamte Angabe in einem nichttrennbaren Block zusammengehalten wird.

import React from 'react';

const formatBibleRef = (text, bracket = false) => {
    if (!text) return null
    const originalText = bracket ? `(${text})` : text;
    let formattedText = text
        .replace(/-/g, '–')
        .replace(/°°°/g, '¥')
        .replace(/°/g, ' ')
        .replace(/\u00a0/g, ' ');
    formattedText = formattedText.replace(/[ ]+/g, ' ');

    // Leerzeichen vor und nach relevanten Satzzeichen entfernen
    [',', '.', ';', '–'].forEach(punct => {
        formattedText = formattedText.replace(new RegExp(`[ ]*\\${punct}[ ]*`, 'g'), punct);
    });
    formattedText = formattedText
        .replace(/vgl.|Vgl./g, 'vgl. ')
        .replace(/cf.|Cf./g, 'cf. ');

    let result = [];
    let currentText = '';
    let inVerseSection = false;

    const addCurrentText = () => {
        if (currentText) {
            if (inVerseSection) {
                result.push(
                    <span className='format-verse' key={`verse-${result.length}`}>
                        {currentText}
                    </span>
                );
            } else {
                result.push(currentText);
            }
            currentText = '';
        }
    };

    for (let i = 0; i < formattedText.length; i++) {
        const char = formattedText[i];
        const nextPunctuation = formattedText.slice(i + 1).match(/[,.;–=]/);
        const nextPunctuationType = nextPunctuation ? nextPunctuation[0] : null;

        switch (char) {
            case '@': return originalText.replace('@', '');
            case '¥':
                if (inVerseSection) {
                    addCurrentText();
                    inVerseSection = false;
                }
                currentText += '¥';
                break;

            case ' ':
                if (inVerseSection) {
                    addCurrentText();
                    inVerseSection = false;
                }
                currentText += '\u00A0';
                break;

            case ',':
                if (inVerseSection) { return originalText; }
                addCurrentText();
                inVerseSection = true;
                currentText += ',';
                break;

            case ';':
                if (!inVerseSection) { return originalText; }
                addCurrentText();
                inVerseSection = false;
                currentText += '; ';
                break;

            case '–':
                if (!inVerseSection) {
                    addCurrentText();
                    currentText += '–\u2060';
                } else {
                    if (!nextPunctuationType) {
                        currentText += '–\u2060';
                    } else if (nextPunctuationType === ',') {
                        addCurrentText();
                        inVerseSection = false;
                        currentText += '\u00a0–\u00A0';
                    } else if (nextPunctuationType === '–') {
                        return originalText;
                    } else {
                        currentText += '–\u2060';
                    }
                }
                break;

            default:
                currentText += char;
        }
    }

    addCurrentText();

    // Doppelte ° durch einzelnes ° ersetzen
    const finalResult = result.map(item =>
        typeof item === 'string'
            ? item
                .replace(/\u00A0\u00A0/g, '\u00a0')
                .replace(/¥/g, '\u00A0\u00A0\u00A0')
            : React.cloneElement(item, {},
                item.props.children
                    .replace(/\u00A0\u00A0/g, '\u00A0')
                    .replace(/¥/g, '\u00A0\u00A0\u00A0'))
    );

    let output = finalResult.length > 0 ? <>{finalResult}</> : originalText;

    // Optional in Klammern einschließen
    if (bracket) { output = <>({output})</>; }

    return output;
};

export default formatBibleRef;