import React, { useState, useMemo, useEffect } from 'react';
import { psalmsData } from '../data/PsHymn.ts'; // Import hinzufügen

const HymnSelector = ({ texts, hour, season,
    prefSource, prefSollemnity,
    localPrefKomplet, localPrefLanguage = '',
    formatPrayerText }) => {
    const [selectedHymn, setSelectedHymn] = useState(null);

    localPrefLanguage = ['_neu', '_ben'].includes(localPrefLanguage) ? '' : localPrefLanguage
    if (hour === 'vesper' && prefSollemnity === 'soll')
        hour = 'prefsollemnity';
    const isErsteVesper = hour === 'vesper' && texts?.rank?.hasErsteVesper && !prefSollemnity

    // Neue Hilfsfunktion zum Auflösen der Hymnen-Referenz
    const resolveHymnReference = (ref) => {
        if (!ref) return null;

        const wholePart = Math.floor(ref);
        const decimalStr = (ref % 1).toFixed(3).split('.')[1];
        const multiplier = decimalStr.replace(/0+$/, '').length === 1 ? 10 : 1000;
        const decimalPart = Math.round((ref % 1) * multiplier);

        return psalmsData[wholePart]?.[decimalPart] || {};
    };

    const getButtonColor = (sourcePath, sourceLabel) => {
        const hasOnlyWtSources = availableHymns.every(
            // wt und pers ungültig gemacht für Färbung der Buttons in allen Fällen
            hymn => ['wtt', 'perss'].includes(hymn.id.split('_')[0]));

        if (sourcePath === 'wt' && !hasOnlyWtSources) {
            if (['vesper', 'komplet'].includes(hour)) {
                // Erste Vesper und Komplet zum 1. Advent und zu Weihnachten
                if (texts?.swd.combined === 'j-34-6') return 'btn-violett';
                if (texts?.date?.mmdd === '12-24') return 'btn-gold';
            }
            if (texts?.laudes?.wt?.farbe === 'r' ||
                (hour === 'vesper' && texts?.vesper?.wt?.farbe === 'r')) {
                return 'btn-red';
            } else if (season === 'j' && !['j-1-0', 'j-34-0'].includes(texts?.swd.combined))
                return 'btn-green';
            else if (season === 'a' || season === 'q')
                return 'btn-violett';
            else return 'btn-gold';
        };

        // Prüfe auf rote Farbe im prefSource
        const pathParts = sourcePath.split('_')[0].split('.');
        let currentLevel = texts.laudes;
        if (isErsteVesper)
            currentLevel = texts.vesper

        pathParts.forEach(part => {
            currentLevel = currentLevel?.[part];
        });

        const color = currentLevel?.farbe;
        if (color?.startsWith('r')) { return 'btn-red' }
        if (color?.startsWith('m')) { return 'btn-blue' }
        if (sourceLabel.startsWith('eigen')) { return 'btn-gold'; }
        if (sourceLabel === 'Comm:') { return 'btn-brown'; }
        if (sourceLabel === 'pers:') { return 'btn-pers'; }
        return 'btn-default'
    };

    const removeAccents = (text) => {
        if (!text) return '';
        if (localPrefLanguage !== '_lat') return text
        return text
            .replace(/[áéíóúý]/g, (match) => match.normalize('NFD').charAt(0))
            .replace(/[ÁÉÍÓÚÝ]/g, (match) => match.normalize('NFD').charAt(0))
            .replace(/[ǽ]/g, 'æ')
            .replace(/[Ǽ]/g, 'Æ')
            .replace('^/', ' ')
            .replace('^ß', ' ');
    };

    const hasEigenHymn = (sourceData) => {
        if (!sourceData?.hymn_1) return false;

        const hymnData = resolveHymnReference(sourceData.hymn_1);
        const title = hymnData?.title || '';

        // Wenn der Titel mit ^[ beginnt, ist es kein eigener Hymnus
        return !title.startsWith('^[');
    };

    const sourceOrder = useMemo(() => {
        // Prüfe die Ränge
        let rank_wt = texts?.rank?.wt || 0
        // Weihnachtsoktav (rank_wt = 2.4): nur Vesper mit Vorrang vor Festen
        rank_wt = hour === 'vesper' ? Math.ceil(rank_wt) : rank_wt

        // Mutter der Kirche und Herz Mariae: rank.date ist zwar 0, aber rank.aroundPentecost=2
        const aroundPentecost = texts?.rank?.aroundPentecost || 0

        const rank_date = texts?.rank?.date || texts?.rank?.aroundPentecost || 0

        const compareRanks =
            isErsteVesper
                ? (texts?.rank?.nextWt || 0) > (texts?.rank?.nextDate || 0)
                : rank_wt >= rank_date

        let useWt = ((prefSollemnity || aroundPentecost)
            && !['terz', 'sext', 'non'].includes(hour))
            ? '' : 'wt'

        const isHighRank = rank_date > 2 || rank_wt > 2 || aroundPentecost ||
            (isErsteVesper && texts?.vesper?.prefComm);

        // Stelle die Basis-Quellen zusammen
        let sources = [prefSource, 'pers'];

        // Wenn der wt-Rang höher oder gleich ist, stehen die wt-Sources zuerst,
        // sonst werden weiter unten die Commune-Sources vorangestellt
        if (isHighRank && compareRanks) {
            sources = ['wt', ...sources];
            useWt = ''
        }

        // Ermittle Commune-Sources nur wenn nötig
        const communeSources = (
            (!texts?.rank?.isCommemoration || prefSollemnity === 'soll') &&
            !hasEigenHymn(texts[hour]?.[prefSource])
        )
            ? ['com1', 'com2']
                .filter(com =>
                    texts[hour]?.[prefSource]?.[com]?.hymn_1 || // Geändert
                    texts[hour]?.[prefSource]?.[com]?.hymn_2    // Geändert
                )
                .map(com => `${prefSource}.${com}`)
            : [];

        // Füge die Sources in der richtigen Reihenfolge hinzu
        if (isHighRank) {
            sources = [...sources, ...communeSources, useWt];
        } else {
            sources = [...sources, useWt, ...communeSources];
        }

        if (hour === 'komplet') { sources = ['pers', 'wt'] }

        return sources;
    }, [texts, hour, prefSource, prefSollemnity]);

    // Sammle alle verfügbaren Hymnen
    const availableHymns = useMemo(() => {
        const collectHymns = (localPrefLanguage = '') => {
            const hymns = [];
            const usedHymnNumbers = new Set();
            const hasNachtHymn = texts[hour]?.wt?.[`hymn_nacht${localPrefLanguage}`];

            const addNewHymn = ({ hymnNumber, id, sourceLabel, isNachtHymn = false, languageSuffix = '' }) => {
                // Korrigierte Logik: Nur verarbeiten wenn hymnNumber existiert und noch nicht verwendet
                if (hymnNumber && !usedHymnNumbers.has(hymnNumber)) {
                    // Löse die Referenz auf, um Text und Titel zu bekommen
                    const hymnData = resolveHymnReference(hymnNumber);

                    // Prüfe auf gewünschte Sprache
                    languageSuffix = languageSuffix || localPrefLanguage;
                    const textField = `text${languageSuffix}`;
                    const titleField = `title${languageSuffix}`;

                    const hymnText = hymnData?.[textField]?.replace('LEER', '')
                    const hymnTitle = hymnData?.[titleField]
                        || hymnText?.split('^l')[0]
                            .trim()
                            .replace(/[.!?,:;-]+$/, '')
                            .replace('^/', ' ')
                            .replace('>', '')
                        || ''
                    const stb3 = (['kl. Stb:', 'pers:'].includes(sourceLabel)
                        && hymnData?.stb3) ? hymnData.stb3 : ''

                    // Nur hinzufügen, wenn der Text in der gewünschten Sprache existiert
                    if (!hymnText) return;

                    hymns.push({
                        id,
                        source: sourceLabel,
                        indent: sourceLabel.length > 9 ? '20' : '',
                        stb3,
                        text: hymnText,
                        title: hymnTitle,
                        hymnNumber,
                        isNachtHymn,
                    });

                    usedHymnNumbers.add(hymnNumber);
                }
            }

            const specialHymns = dataSpecialHymns?.[prefSollemnity]?.[localPrefLanguage]?.[hour]
                || dataSpecialHymns?.[prefSollemnity]?.[hour];
            const hymnNumbers = Array.isArray(specialHymns) ? specialHymns : [specialHymns];

            hymnNumbers?.forEach((specialHymn, index) => {
                addNewHymn({
                    hymnNumber: specialHymn,
                    id: `${prefSollemnity}_hymn_${index + 1}`,
                    sourceLabel: prefSollemnity?.charAt(0).toUpperCase() + prefSollemnity?.slice(1),
                    isNachtHymn: false
                });
            });

            let hymnTypes = ['hymn_nacht', 'hymn_1', 'hymn_2', 'hymn_3',
                'hymn_nacht_lat', 'hymn_1_lat', 'hymn_2_lat', 'hymn_3_lat', 'hymn_kl'];
            if (prefSollemnity) {
                hymnTypes = ['hymn_1', 'hymn_2', 'hymn_3',
                    'hymn_1_lat', 'hymn_2_lat', 'hymn_3_lat']
            }

            // Durchlaufe die Quellen in der festgelegten Reihenfolge
            sourceOrder.forEach(sourcePath => {
                const pathParts = sourcePath.split('.');
                let currentLevel = texts[hour];
                pathParts.forEach(part => {
                    currentLevel = currentLevel?.[part];
                });

                if (!currentLevel) return;

                hymnTypes.forEach(hymnType => {
                    if (currentLevel?.[hymnType]) {
                        const hymnNumber = currentLevel[hymnType];

                        let sourceLabel;
                        if (sourcePath === prefSource) {
                            sourceLabel = 'eigen:';
                        } else if (sourcePath === prefSollemnity) {
                            sourceLabel = prefSollemnity.charAt(0).toUpperCase() + prefSollemnity.slice(1);
                        } else if (sourcePath === 'pers') {
                            sourceLabel = 'pers:';
                        } else if (['wt', 'k1', 'k2'].includes(sourcePath)) {
                            if (hymnType.startsWith('hymn_nacht')) {
                                sourceLabel = 'In der Nacht oder am frühen Morgen:';
                            } else if (hymnType === 'hymn_kl') {
                                sourceLabel = 'kl. Stb:';
                            } else if (hymnType === 'hymn_1' && hasNachtHymn) {
                                sourceLabel = 'Am Tag:';
                            } else {
                                sourceLabel = 'vom Tag:';
                            }
                        } else {
                            sourceLabel = 'Comm:';
                        }

                        addNewHymn({
                            hymnNumber,
                            id: `${sourcePath.replace('.', '_')}_${hymnType}`,
                            sourceLabel,
                            isNachtHymn: hymnType.startsWith('hymn_nacht')
                        });
                    }
                });
            });

            // Spezielle Komplet-Hymnen hinzufügen
            if (hour === 'komplet') {
                const kompletHymnNumber = dataSpecialHymns[localPrefKomplet];

                // Verwende die addNewHymn Funktion auch hier
                addNewHymn({
                    hymnNumber: kompletHymnNumber,
                    id: 'wt_hymn_k',
                    sourceLabel: 'vom Tag:',
                    isNachtHymn: false
                });
            }

            // NEUER SUCHLAUF: Prüfe nach eigenen Hymnen in anderen Sprachen
            // Nur wenn prefSource === 'oblig' und für das Feld hymn_1
            if (texts[hour]?.oblig) {
                const eigData = texts[hour].oblig;

                // Prüfe, ob hymn_1 in der aktuellen Sprache bereits vorhanden ist
                const currentLanguageHymn1 = eigData?.hymn_1 || 0

                // Wenn kein hymn_1 in der aktuellen Sprache vorhanden ist,
                // suche nach hymn_1 mit Sprachsuffixen
                if (currentLanguageHymn1 < 8000) {
                    // Definiere mögliche Sprachsuffixe (erweitere bei Bedarf)
                    const languageSuffixes = ['_lat', '_gr'];

                    languageSuffixes.forEach(suffix => {
                        const alternativeHymnField = `hymn_1${suffix}`;
                        const alternativeHymnNumber = eigData[alternativeHymnField];
                        if (alternativeHymnNumber > 8000) {
                            // Erstelle eindeutige ID für diesen alternativen Hymnus
                            const alternativeId = `oblig_${alternativeHymnField}_fallback`;

                            // Bestimme Sprachkennzeichnung für das Label
                            let languageLabel = suffix.replace(/^_(.+)$/, ' ($1.)');
                            //languageLabel = ''
                            addNewHymn({
                                hymnNumber: alternativeHymnNumber,
                                id: alternativeId,
                                sourceLabel: `eigen${languageLabel}:`,
                                isNachtHymn: false,
                                languageSuffix: suffix
                            });
                        }
                    });
                }
            }

            return hymns;
        };

        // Erster Durchlauf: Mit Sprachpräferenz (oder Standard wenn nicht gesetzt)
        const firstPass = collectHymns(localPrefLanguage);
        if (firstPass.length > 0) {
            return firstPass;
        }

        // Fallback: Standard-Sprache (nur wenn erster Durchlauf leer war)
        return collectHymns('');

    }, [texts, hour, prefSource, sourceOrder, localPrefLanguage, localPrefKomplet]);

    // Setze den ersten gefundenen Hymnus als ausgewählt
    useEffect(() => {
        if (availableHymns.length > 0) {
            setSelectedHymn(availableHymns[0].id);
        }
    }, [availableHymns]);

    if (availableHymns.length === 0) return null;

    if (availableHymns.length === 1) {
        return (
            <div className="w-full -mb-2">
                {formatPrayerText(availableHymns[0].text)}
            </div>
        );
    }

    return (
        <div className="w-full">
            {availableHymns.map((hymn) => (
                <button
                    key={hymn.id}
                    onClick={() => setSelectedHymn(hymn.id)}
                    className={`w-full text-sm text-left px-2 pt-2 pb-1 mt-1 rounded
                        ${getButtonColor(hymn.id.split('_')[0], hymn.source)}
                        ${selectedHymn === hymn.id ? 'ring-2 ring-[#b6a03a]' : ''}`}
                    aria-hidden="true">
                    {hymn.isNachtHymn ? (
                        <div className="flex flex-col gap-0">
                            <div className="opacity-70">
                                {hymn.source}
                            </div>
                            <div className="pl-16">
                                {formatPrayerText(removeAccents(hymn?.title))}
                            </div>
                        </div>
                    ) : (
                        <div className="flex items-baseline gap-0"
                            aria-hidden="true">
                            <div className={`opacity-70 shrink-0 ${hymn.indent ? 'w-20' : 'w-16'}`}>
                                {hymn.source}
                            </div>
                            <div>
                                {formatPrayerText(removeAccents(hymn?.title))}
                            </div>
                        </div>
                    )}
                </button>
            ))}

            {availableHymns.find(h => h.id === selectedHymn)?.stb3 && (
                <div className="mt-3 -mb-3 long-rubric" aria-hidden="true">
                    Stundenbuch III/
                    {formatPrayerText(
                        availableHymns.find(h => h.id === selectedHymn)?.stb3
                    )}
                </div>
            )}
            {selectedHymn && (
                <div className="mt-5 -mb-2">
                    {formatPrayerText(
                        availableHymns.find(h => h.id === selectedHymn)?.text
                    )}
                </div>
            )}
        </div>
    );
};

export default HymnSelector;

const dataSpecialHymns = {
    "k1": 2516,
    "k2": 2510,
    "kirchw": {
        "erstev": 1154,
        "lesehore": 1139,
        "laudes": 1150,
        "vesper": 1154,
        "_lat": {
            "erstev": 5450,
            "lesehore": 5436,
            "laudes": 5446,
            "vesper": 5450,
        },
    },
    "verst": {
        "lesehore": [2514, 1425],
        "laudes": 1440,
        "terz": 1440,
        "sext": 1440,
        "non": 1440,
        "vesper": 2512,
        "_lat": {
            "lesehore": [5698.1, 5698.2, 5698.3],
            "laudes": [5708.1, 5708.2, 5708.3],
            "terz": [5713.1, 5713.2, 5713.3],
            "sext": [5716.1, 5716.2, 5716.3],
            "non": [5719.1, 5719.2, 5719.3],
            "vesper": [5720.1, 5720.2, 5720.3],
        }
    }
}