import { tableOfRanks } from '../data/TableOfRanks.js';

const daysToMilliseconds = (days) => days * 24 * 60 * 60 * 1000;

const writeOut = (season, week, dayOfWeek, swdCombined, day, aroundEpiphany, aroundPentecost) => {

    const days = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];
    const dayName = days[dayOfWeek];

    // Spezielle Festtage basierend auf swdCombined bzw. aroundPentecost
    const specialFeastDays = {
        'w-1-0': 'Fest der Heiligen Familie',
        67: 'Fest der Taufe Jesu',
        'q-6-0': 'Palmsonntag',
        'q-6-4': 'Gründonnerstag',
        'q-6-5': 'Karfreitag',
        'q-6-6': 'Karsamstag',
        'o-1-0': 'Ostersonntag',
        'o-1-1': 'Ostermontag',
        'o-2-0': 'Weißer Sonntag – Sonntag\u00a0der\u00a0Göttlichen\u00a0Barmherzigkeit',
        40: 'Christi Himmelfahrt',
        'o-8-0': 'Pfingstsonntag',
        'o-8-1': 'Pfingstmontag',
        60: 'Dreifaltigkeitssonntag',
        64: 'Fronleichnam',
        65: 'Herz-Jesu-Fest',
        'j-34-0': 'Christkönigssonntag'
    };

    // Prüfe zuerst auf spezielle Festtage
    const specialFeast = aroundEpiphany || aroundPentecost || swdCombined
    if (specialFeastDays[specialFeast]) {
        return specialFeastDays[specialFeast];
    }

    // Spezielle Behandlung für die Aschermittwochswoche (0. Fastenwoche)
    if (season === 'q' && week === 0) {
        if (dayOfWeek === 3) return "Aschermittwoch";
        else if (dayOfWeek > 3)   // Donnerstag, Freitag, Samstag
            return `${dayName} nach Aschermittwoch`;
    }

    if (season === 'w' && (day > 24 || day === 1)) {
        if (day === 25) return 'Weihnachten';
        if (day === 1) return 'Neujahr';
        if (day > 25) return `${dayName} in der Weihnachtsoktav`
    };

    if (season === 'q' && week === 6)
        return `${dayName} der Karwoche`

    if (season === 'o' && week === 1)
        return `${dayName} der Osteroktav`

    // Spezielle Formatierung für Sonntage
    if (dayOfWeek === 0) {
        switch (season) {
            case 'a': return `${week}. Adventssonntag`;
            case 'w': return `${week}. Sonntag nach Weihnachten`;
            case 'j': return `${week}. Sonntag im Jahreskreis`;
            case 'q': return `${week}. Fastensonntag`;
            case 'o': return `${week}. Sonntag der Osterzeit`;
            default: return '';
        }
    }

    // Reguläre Formatierung für andere Wochentage
    const regularDayName = `${dayName} der ${week}.\u00a0`
    switch (season) {
        case 'a': return `${regularDayName}Adventswoche`;
        case 'w': return `${regularDayName}Woche der\u00a0Weihnachtszeit`;
        case 'j': return `${regularDayName}Woche im\u00a0Jahreskreis`;
        case 'q': return `${regularDayName}Fastenwoche`;
        case 'o': return `${regularDayName}Woche der\u00a0Osterzeit`;
        default: return '';
    }
};

// Helper function to calculate rank for a specific date
function calculateRanks(date, season, week, dayOfWeek, swdCombined, aroundEpiphany, aroundPentecost) {

    const month = date.getMonth() + 1;
    const day = date.getDate();

    const ordinalNumber = Math.ceil(day / 7);
    const lastDayOfMonth = new Date(date.getFullYear(), month, 0).getDate();
    const ordinalLastNumber = Math.ceil((lastDayOfMonth - day + 1) / 7);

    const mmdd = `${month.toString().padStart(2, '0')}-${day.toString().padStart(2, '0')}`;
    const ordinal = `${month}-${ordinalNumber}-${dayOfWeek}`;
    const ordinalLast = `${month}-L${ordinalLastNumber}-${dayOfWeek}`;

    // Rank für Wochentag (rank_wt) bestimmen
    function calculateRankWt() {
        // Sonderfall: Christi Himmelfahrt und Feste nach Pfingsten
        if (aroundEpiphany === 67) return 4
        if ([40, 60, 64, 65].includes(aroundPentecost)) return 5

        // 1. Grundsätzlich sind alle Sonntage Rang 5
        if (dayOfWeek === 0) {
            // 2. Ausnahme: Sonntage in der Weihnachtszeit und im Jahreskreis (außer Christkönig) sind Rang 3
            if ((season === 'j' && week !== 34) || season === 'w')
                return 3;
            return 5;
        }

        // 3. Karwoche und Osteroktav
        if (swdCombined.startsWith('q-6-')) return 5;
        if (swdCombined.startsWith('o-1-')) return 5;

        // 4. Aschermittwoch
        if (swdCombined === 'q-0-3') return 5;

        // 6. Gebotene Gedenktage und Kommemoration
        if (season === 'q') return 2;           // Wochentage der Fastenzeit
        if (month === 12 && day > 25) return 2.4;   // Weihnachtsoktav
        if (month === 12 && day > 16) return 2;   // letzte Adventstage und Weihnachtszeit

        return 0; // Standard-Rang für alle anderen Tage
    }

    // Rank für Datum (rank_date) bestimmen
    function calculateRankDate() {
        const diocese = localStorage.getItem('diocese') || 'Fulda';

        // Sonderfall: Epiphanie (6. Januar) kann in manchen Diözesen auf den Sonntag nach dem 1. Januar verlegt werden
        if (aroundEpiphany === 66) return 5; // 66 für Epiphanie, 67 für Taufe des Herrn

        // Schleife durch die Ränge (von hoch zu niedrig)
        for (const rank of [6, 5, 4, 3, 2]) {
            if (tableOfRanks?.[diocese]?.[rank]?.includes(mmdd)) return rank;
            if (tableOfRanks?.[diocese]?.[rank]?.includes(ordinal)) return rank;
            if (tableOfRanks?.[diocese]?.[rank]?.includes(ordinalLast)) return rank;
        }
        for (const rank of [6, 5, 4, 3, 2]) {
            if (tableOfRanks?.[rank]?.includes(mmdd)) return rank;
            if (tableOfRanks?.[rank]?.includes(ordinal)) return rank;
            if (tableOfRanks?.[rank]?.includes(ordinalLast)) return rank;
        }
        return 0; // Kein spezieller Rang gefunden
    }

    function calculateHasVigil() {
        // nur Feste und Hochfeste haben eine Vigil
        if (calculateRankWt() < 3 && calculateRankDate() < 3)
            return false;
        // Aschermittwoch trotz Rang 5 keine Vigil
        if (swdCombined === 'q-0-3') return false;
        // in der Karwoche trotz Rang 5 nur Palmsonntag, Karfreitag und Karsamstag
        if (swdCombined.startsWith('q-6-') && (dayOfWeek + 2) % 7 > 2)
            return false;
        // in der Osteroktav trotz Rang 5 keine Vigil
        // (Lesehore/Vigil am Ostersonntag hat eine eigene Struktur: MatutinDisplay.js)
        if (swdCombined.startsWith('o-1-')) return false;
        return true;
    }

    if (!date || !(date instanceof Date)) {
        console.error('Invalid date provided to calculateRanks:', date);
        return { rank_wt: 0, rank_date: 0, hasVigil: false };
    }

    if (!season) {
        console.error('No season provided to calculateRanks for date:', date);
        return { rank_wt: 0, rank_date: 0, hasVigil: false };
    }

    if (week === undefined || week === null) {
        console.error('No week provided to calculateRanks for date:', date);
        return { rank_wt: 0, rank_date: 0, hasVigil: false };
    }

    return {
        rank_wt: calculateRankWt(),
        rank_date: calculateRankDate(),
        hasVigil: calculateHasVigil(),
        date: { mmdd, ordinal, ordinalLast }
    }
}

// Calculate Easter using Meeus/Jones/Butcher algorithm
const calculateEaster = (year) => {
    const a = year % 19;
    const b = Math.floor(year / 100);
    const c = year % 100;
    const d = Math.floor(b / 4);
    const e = b % 4;
    const f = Math.floor((b + 8) / 25);
    const g = Math.floor((b - f + 1) / 3);
    const h = (19 * a + b - d - g + 15) % 30;
    const i = Math.floor(c / 4);
    const k = c % 4;
    const l = (32 + 2 * e + 2 * i - h - k) % 7;
    const m = Math.floor((a + 11 * h + 22 * l) / 451);
    const month = Math.floor((h + l - 7 * m + 114) / 31);
    const day = ((h + l - 7 * m + 114) % 31) + 1;

    return new Date(Date.UTC(year, month - 1, day));
};

// Get next Sunday after or on the given date
const getNextSunday = (date) => {
    const d = new Date(date);
    const dayToSunday = 7 - d.getDay();
    d.setUTCDate(d.getUTCDate() + dayToSunday);
    return d;
};

// Get liturgical information for a given date
const getLiturgicalInfo = (provDate) => {
    // Normalisiere das Eingabedatum auf Mitternacht
    const date = new Date(Date.UTC(
        provDate.getFullYear(),
        provDate.getMonth(),
        provDate.getDate()
    ));

    const year = date.getUTCFullYear();
    const month = date.getUTCMonth() + 1;
    const day = date.getUTCDate();
    const dayOfWeek = date.getUTCDay();

    // Berechne Schlüsseldaten und normalisiere sie
    const stored = localStorage.getItem('delaySolemnity');
    const delaySolemnity = stored ? JSON.parse(stored) : { epiphany: false, ascension: 0, corpusXP: 0 };

    const christmas = new Date(Date.UTC(year - 1, 11, 25));
    const christmasSunday = getNextSunday(christmas);
    const epiphanyDate = delaySolemnity.epiphany
        ? getNextSunday(new Date(Date.UTC(year, 0, 1)))
        : new Date(Date.UTC(year, 0, 6));
    const baptism = (delaySolemnity.epiphany && epiphanyDate.getUTCDate() >= 7)
        ? new Date(Date.UTC(year, 0, epiphanyDate.getUTCDate() + 1))
        : getNextSunday(epiphanyDate);
    const easter = calculateEaster(year);
    const lentSunday = new Date(easter.getTime() - daysToMilliseconds(42));
    const pentecost = new Date(easter.getTime() + daysToMilliseconds(49));
    const advent = new Date(Date.UTC(year, 11, 25));
    advent.setUTCDate(advent.getUTCDate() - (advent.getUTCDay() || 7) - 21);

    const daysSinceEaster = Math.floor((date - easter) / daysToMilliseconds(1));

    const aroundEpiphany =
        date.getTime() === epiphanyDate.getTime() ? 66
            : date.getTime() === baptism.getTime() ? 67
                : null;

    const aroundPentecost =
        daysSinceEaster === 39 + delaySolemnity.ascension ? 40
            : daysSinceEaster === 60 + delaySolemnity.corpusXP ? 64
                : [50, 56, 68, 69].includes(daysSinceEaster) ? 60 + (daysSinceEaster % 7)
                    : [66, 67].includes(daysSinceEaster) // Offset für Mi und Do vor Herz-Jesu-Fest
                        ? 68 - daysSinceEaster
                        : null;

    // Helper function for week calculation
    const weeksBetween = (start, current) =>
        Math.floor((current - start) / daysToMilliseconds(7)) + 1;

    let season, week, weekOfPsalter;

    // Christmas Season until Baptism
    if (date < baptism) {
        season = 'w';
        week = weeksBetween(christmasSunday, date);
    }
    else if (date === baptism) {
        season = 'j';
        week = 1
        weekOfPsalter = weeksBetween(christmasSunday, date);
    }
    // Ordinary Time before Ash Wednesday
    else if (date < lentSunday - daysToMilliseconds(4)) {
        season = 'j';
        week = weeksBetween(baptism, date);
    }
    // Ash Wednesday until First Sunday of Lent
    else if (date < lentSunday) {
        season = 'q';
        week = 0;
    }
    // Lent and Holy Week
    else if (date < easter) {
        season = 'q';
        week = weeksBetween(lentSunday, date);
    }
    // Easter through Pentecost
    else if (date <= pentecost) {
        season = 'o';
        week = weeksBetween(easter, date);
    }
    // Ordinary Time after Pentecost
    else if (date < advent) {
        season = 'j';
        week = 34 - Math.floor((advent - date - 1) / daysToMilliseconds(7));
    }
    // Advent
    else if (date >= advent) {
        const adventWeek = weeksBetween(advent, date);
        if (adventWeek < 5) {
            season = 'a';
            week = adventWeek;
        } else {
            season = 'w';
            week = 1;
        }
    }

    if (season === 'a' && week === 4 && day > 24) {
        season = 'w'; week = 0;
    }
    const swdCombined = `${season}-${week}-${dayOfWeek}`;
    const swdWritten = writeOut(season, week, dayOfWeek, swdCombined, day, aroundEpiphany, aroundPentecost);
    weekOfPsalter = weekOfPsalter ?? (week % 4 || 4)
    const ranks = calculateRanks(date, season, week, dayOfWeek, swdCombined, aroundEpiphany, aroundPentecost);
    const isCommemoration = ranks.rank_date < 3 &&
        (season === 'q' || (month === 12 && day > 16));

    return {
        season,
        week,
        dayOfWeek,
        weekOfPsalter,
        swdCombined,
        swdWritten,
        swd: {
            combined: swdCombined,
            written: swdWritten,
        },
        ...ranks,  // Fügt rank_wt und rank_date zum Return-Objekt hinzu
        aroundEpiphany,
        aroundPentecost,
        isCommemoration,
    };
};

export { getLiturgicalInfo };